#!/usr/bin/env bash
# Replay the migration chain from zero and VERIFY THE RESULT — do not trust the exit code.
#
# Why this exists: `supabase db reset` exited 0 while a migration failed with
# "cannot change name of view column". The failure was invisible because the caller discarded output
# and believed the status. A migration gate that can pass while a migration failed is not a gate.
#
# Two independent checks:
#   1. grep the replay output for any ERROR line
#   2. assert the objects the chain is supposed to have produced actually exist
#
# Usage: scripts/verify-replay.sh        (from the repo root)
# Exit:  0 = replay clean AND every expected object present; non-zero otherwise.

set -euo pipefail

DB="${SB_DB_URL:-postgresql://postgres:postgres@127.0.0.1:54322/postgres}"

# Loopback only. This script resets a database; it must never be pointed at a shared one.
host="$(printf '%s' "$DB" | sed -E 's#.*://[^@]*@([^:/]+).*#\1#')"
case "$host" in
  127.0.0.1|localhost|::1) ;;
  *) echo "REFUSING: $host is not loopback. This script RESETS the database." >&2; exit 2 ;;
esac

echo "== replaying migrations from zero =="
out="$(scripts/sb.sh db reset 2>&1)" || { echo "$out" | tail -30; echo "FAIL: db reset exited non-zero"; exit 1; }

if printf '%s' "$out" | grep -qiE '^error|ERROR:'; then
  echo "FAIL: the replay emitted errors even though it exited 0 —"
  printf '%s' "$out" | grep -iE '^error|ERROR:' | head -20
  exit 1
fi
echo "   no error lines in replay output"

echo "== verifying the objects the chain must have produced =="
