fail=0
while IFS='|' read -r name sql; do
  [ -z "$name" ] && continue
  n="$(psql "$DB" -tAc "$sql" | tr -d '[:space:]')"
  if [ "${n:-0}" -ge 1 ]; then printf '   ok   %s (%s)\n' "$name" "$n"
  else printf '   FAIL %s — expected >=1, got %s\n' "$name" "${n:-0}"; fail=1; fi
done <<< "$checks"

